/// Go: `var commandLineOptionEnumMap = map[string]*collections.OrderedMap[string, any]{...}`.
pub fn command_line_option_enum_map(
    name: &str,
) -> Option<&'static OrderedMap<String, CompilerOptionsValue>> {
    match name {
        "jsx" => Some(jsx_option_map()),
        "lib" => Some(lib_map()),
        "module" => Some(module_option_map()),
        "moduleDetection" => Some(module_detection_option_map()),
        "moduleResolution" => Some(module_resolution_option_map()),
        "newLine" => Some(new_line_option_map()),
        "target" => Some(target_option_map()),
        _ => None,
    }
}

/// Go: `var commandLineOptionDeprecated = map[string]*collections.Set[string]{...}`.
///
/// PORT: Go returns a *Set; the port returns a static slice with identical
/// membership semantics (formatEnumTypeKeys filters by `DeprecatedKeys().Has`).
pub fn command_line_option_deprecated(name: &str) -> Option<&'static [&'static str]> {
    match name {
        "module" => Some(&["none", "amd", "system", "umd"]),
        "moduleResolution" => Some(&["node", "classic", "node10"]),
        "target" => Some(&["es5"]),
        _ => None,
    }
}

/// Go: `var targetToLibMap = map[core.ScriptTarget]string{...}`.
pub fn target_to_lib(target: ScriptTarget) -> Option<&'static str> {
    match target {
        ScriptTarget::ESNext => Some("lib.esnext.full.d.ts"),
        ScriptTarget::ES2026 => Some("lib.es2026.full.d.ts"),
        ScriptTarget::ES2025 => Some("lib.es2025.full.d.ts"),
        ScriptTarget::ES2024 => Some("lib.es2024.full.d.ts"),
        ScriptTarget::ES2023 => Some("lib.es2023.full.d.ts"),
        ScriptTarget::ES2022 => Some("lib.es2022.full.d.ts"),
        ScriptTarget::ES2021 => Some("lib.es2021.full.d.ts"),
        ScriptTarget::ES2020 => Some("lib.es2020.full.d.ts"),
        ScriptTarget::ES2019 => Some("lib.es2019.full.d.ts"),
        ScriptTarget::ES2018 => Some("lib.es2018.full.d.ts"),
        ScriptTarget::ES2017 => Some("lib.es2017.full.d.ts"),
        ScriptTarget::ES2016 => Some("lib.es2016.full.d.ts"),
        ScriptTarget::ES2015 => Some("lib.es6.d.ts"), // Use lib.es6.d.ts for compatibility rather than lib.es2015.full.d.ts.
        _ => None,
    }
}
